// readOnlyRemote is set once a remote window connects (#240); see
// readonly.ts.
let readOnlyRemote = false;
let readOnlyMessage = 'Read-only remote (coming in a later version)';
export function setReadOnlyRemote(on: boolean, message: string) {
  readOnlyRemote = on;
  readOnlyMessage = message;
}

// A remote window's calls fail with a WindowError in the user's language
// (readonly.ts); a local window's come back as they are.
export const bridge = guardCalls(calls, () => readOnlyRemote, () => readOnlyMessage, (e) => decodeWindowError(e, get(t)));

// ── Remote mode types (mirror cmd/gui/remote.go) ──
export type RemoteStateName = 'connecting' | 'installing' | 'connected' | 'failed' | 'disconnected';

export interface RemoteState {
  state: RemoteStateName;
  code?: string;
  hint?: string;
  detail?: string;
  alias: string;
  serverOS?: string;
  serverArch?: string;
  serverVersion?: string;
  truncated?: boolean;
  // The editor commands that open folders of the host (#243).
  remoteEditors?: string[] | null;
  // The editor chosen for this remote, absent for Auto (#287).
  editor?: string;
}

export interface RemoteResult {
  error?: string;
  hint?: string;
}

export interface RemoteUninstallResult extends RemoteResult {
  needsConfirm: boolean;
  otherClients: number;
  done: boolean;
  rootKept: boolean;
}

export interface RemoteDoctorReport {
  version: string;
  commit: string;
  os: string;
  arch: string;
  home: string;
  configPath: string;
  configDirWritable: boolean;
  configDirExec: boolean;
  gitVersion: string;
  credentialFindings: CredentialFinding[] | null;
}

export interface RemoteDoctorResult extends RemoteResult {
  report?: RemoteDoctorReport;
}

export interface RemotePathDTO {
  abs: string;
  exists: boolean;
  isDir: boolean;
  writable: boolean;
  error?: string;
}

export interface RemotesList {
  enabled: boolean;
  remotes: { alias: string; serverDir?: string; editor?: string }[];
  // The editor commands a remote can be set to (#287).
  remoteEditors?: string[] | null;
}

// ── Doctor types (mirror cmd/gui/app.go) ──
export interface DoctorToolDTO {
  name: string;
  displayName: string;
  purpose: string;
  found: boolean;
  path?: string;
  version?: string;
  required: boolean;
  requiredFor?: string;
  installHint?: string;
}

export interface DoctorReport {
  credentialFindings: CredentialFinding[];
  tools: DoctorToolDTO[];
  allOk: boolean;
  missingReq: number;
  missingOpt: number;
}

export interface DoctorPrecheckDTO {
  ok: boolean;
  summary?: string;
  hint?: string;
  missing?: DoctorToolDTO[];
}

export const events = {
  on: EventsOn,
};
